const lessons=[['GET ROLLING','Hold the gas pedal to reach 60 km/h.'],['FIND YOUR LINE','Tilt or hold a steering arrow to turn.'],['BRAKE EARLY','Hold the brake pedal to slow down.'],['LIGHT IT UP','Hold gas, then double-tap it to fire your full nitro tank.']];
export function createFirstDrive({start,exit,settings}){
 const intro=document.createElement('section');intro.className='first-drive-intro';intro.hidden=true;intro.setAttribute('role','dialog');intro.setAttribute('aria-label','Welcome to Coastline Rush');intro.innerHTML='<div><small>WELCOME TO THE GRID</small><h2>YOUR FIRST DRIVE</h2><p>A short practice for gas, steering, braking and nitro. No traffic, rewards or saved race results.</p><button data-practice>Start practice ↗</button><button data-skip>Skip intro</button></div>';document.querySelector('.game').append(intro);
 const hud=document.createElement('aside');hud.className='coach-card';hud.hidden=true;hud.innerHTML='<small></small><h3></h3><p></p><button>Exit practice</button>';document.querySelector('.game').append(hud);let index=0,held=0;
 function mark(){try{localStorage.setItem('coast-intro-seen','1');}catch{}}
 intro.querySelector('[data-practice]').onclick=()=>{mark();intro.hidden=true;start();};intro.querySelector('[data-skip]').onclick=()=>{mark();intro.hidden=true;document.querySelector('#start')?.focus();};hud.querySelector('button').onclick=()=>{hud.hidden=true;exit();};intro.addEventListener('keydown',e=>{if(e.key==='Escape')intro.querySelector('[data-skip]').click();if(e.key==='Tab'){const buttons=[...intro.querySelectorAll('button')];e.preventDefault();buttons[(buttons.indexOf(document.activeElement)+(e.shiftKey?-1:1)+2)%2].focus();}});
 function display(){hud.querySelector('small').textContent=(index+1)+' / 4 · PRACTICE';hud.querySelector('h3').textContent=lessons[index][0];hud.querySelector('p').textContent=lessons[index][1];}
 return {welcome(){let seen;try{seen=localStorage.getItem('coast-intro-seen');}catch{}if(!seen){intro.hidden=false;intro.querySelector('[data-practice]').focus();}},begin(){index=0;held=0;hud.hidden=false;display();},hide(){hud.hidden=intro.hidden=true;},get open(){return !intro.hidden;},update(s,input,dt){if(!s.tutorial||s.mode!=='playing')return;if(index===3&&s.nitroTime<=0&&s.nitroUses===0)s.nitro=100;const valid=index===0?s.speed>=60:index===1?Math.abs(input.steer)>.3:index===2?input.brake:s.nitroUses>0;held=valid?held+dt:0;if(held<(index===0||index===3?.1:.45))return;held=0;if(++index===lessons.length){hud.hidden=true;exit(true);}else display();}};
}
